import subprocess, sys

def guess(n):
    return subprocess.check_output(['./guess.py', str(n)]).decode().strip()

def reliable(n):
    a=guess(n); b=guess(n); c=guess(n)
    return a,b,c

minv=1; maxv=1024; ans=None
for i in range(5):
    mid=(minv+maxv)//2
    a,b,c=reliable(mid)
    if 'equals' in (a,b,c):
        ans=mid; break
    higher=(a=='higher')+(b=='higher')+(c=='higher')
    lower=(a=='lower')+(b=='lower')+(c=='lower')
    if higher>lower:
        minv=mid+1
    else:
        maxv=mid-1
    if minv>=maxv:
        ans=minv;break

if ans is None: ans=minv
# final check
guess(ans)
print(ans)
