import subprocess

def guess(n):
    try:
        out=subprocess.run(['./guess.py',str(n)],capture_output=True,text=True,check=True)
        return out.stdout.strip()
    except subprocess.CalledProcessError as e:
        return e.stdout.strip() if e.stdout else ''

def reliable(n):
    a=guess(n);b=guess(n);c=guess(n)
    return a,b,c

lo,hi=1,1024
ans=None
for _ in range(5):
    mid=(lo+hi)//2
    a,b,c=reliable(mid)
    if 'equals' in (a,b,c):
        ans=mid;break
    higher=(a=='higher')+(b=='higher')+(c=='higher')
    lower=(a=='lower')+(b=='lower')+(c=='lower')
    if higher>lower:
        lo=mid+1
    else:
        hi=mid-1
    if lo>=hi:
        ans=lo;break
if ans is None: ans=lo
print(ans)
